        int prev = cur_pyr; cur = 1 - cur_pyr;
        build_pyramid(frame, cur); gov_used += GC_PYR;
#if MAP_MODE
        map_img = cur;
#endif
        double Rwc_now[9];
        m3mul(R, R_bc, Rwc_now);
        gov_klt_cnt = 0;
        track_all(prev, cur, Rwc_now);
        gov_used += gov_klt_cnt * GC_KLT;
#if EDGE
        if (edge_on()) { double Rr[9]; m3tmul(Rwc_now, Rwc_prev, Rr); edge_track_all(cur, Rr); gov_used += edge_alive() * GC_EDGE; }
#endif
